	public static function boot(array $config) {
		self::$option  = $config['option'];
		self::$accent  = $config['accent'];
		self::$version = $config['version'];
		self::$url     = untrailingslashit($config['url']);

		add_action('admin_menu', [__CLASS__, 'admin_menu']);
		add_action('admin_init', [__CLASS__, 'register_setting']);
		add_action('admin_enqueue_scripts', [__CLASS__, 'admin_assets']);
		add_action('admin_bar_menu', [__CLASS__, 'admin_bar'], 80);
		add_action('wp_ajax_wpm_theme_preview', [__CLASS__, 'ajax_preview']);
		add_action('wp_ajax_wpm_list_menus', [__CLASS__, 'ajax_list_menus']);
		add_action('wp_ajax_wpm_create_menu', [__CLASS__, 'ajax_create_menu']);
		add_filter('option_page_capability_' . self::GROUP, function () {
			return 'edit_theme_options';
		});
		add_filter('show_admin_bar', function ($show) {
			return self::is_preview() ? false : $show;
		});

		add_action('add_option_' . self::$option, [__CLASS__, 'flush']);
		add_action('update_option_' . self::$option, [__CLASS__, 'flush']);
		add_action('add_option_' . self::$option, function ($name, $value) {
			self::sync_menu_locations($value);
		}, 10, 2);
		add_action('update_option_' . self::$option, function ($old, $value) {
			self::sync_menu_locations($value);
		}, 10, 2);
	}

	public static function asset_url($path) {
		return self::$url . '/' . ltrim($path, '/');
	}

	public static function version() {
		return self::$version;
	}

	/** Theme version + file mtime, so edited assets are never served stale from browser caches. */
	public static function asset_version($path) {
		$file = get_template_directory() . '/' . ltrim($path, '/');
		return self::$version . '.' . (file_exists($file) ? filemtime($file) : '0');
	}

