	/* ================================================================ values */

	public static function defaults() {
		$values = [];
		foreach (self::schema() as $tab => $tab_def) {
			foreach ($tab_def['sections'] as $section => $section_def) {
				foreach ($section_def['fields'] as $field => $def) {
					$values[$tab][$section][$field] = (string) $def['default'];
				}
			}
		}
		return $values;
	}

	/** Defaults overlaid with the stored values (only known keys, scalars). */
	private static function merge(array $defaults, $stored) {
		if (!is_array($stored)) {
			return $defaults;
		}
		foreach ($defaults as $tab => $sections) {
			foreach ($sections as $section => $fields) {
				foreach ($fields as $field => $default) {
					if (isset($stored[$tab][$section][$field]) && is_scalar($stored[$tab][$section][$field])) {
						$defaults[$tab][$section][$field] = (string) $stored[$tab][$section][$field];
					}
				}
			}
		}
		return $defaults;
	}

	public static function saved() {
		return self::merge(self::defaults(), get_option(self::$option, []));
	}

	/** Values for the current request: saved values, or the draft in the admin preview. */
	public static function all() {
		if (self::$cache !== null) {
			return self::$cache;
		}
		$values = self::saved();
		if (self::is_preview()) {
			$draft = get_transient(self::preview_key());
			if (is_array($draft)) {
				$values = self::merge($values, $draft);
			}
		}
		if (did_action('init')) {
			self::$cache = $values;
		}
		return $values;
	}

	public static function get($tab, $section, $field) {
		$all = self::all();
		return $all[$tab][$section][$field] ?? '';
	}

	public static function flag($tab, $section, $field) {
		return self::get($tab, $section, $field) === '1';
	}

	public static function flush() {
		self::$cache = null;
		if (function_exists('wp_clean_theme_json_cache')) {
			wp_clean_theme_json_cache();
		}
	}

	/* ============================================================== preview */

	private static function preview_key() {
		return 'wpm_preview_' . get_current_user_id();
	}

	public static function is_preview() {
		return !is_admin()
			&& !empty($_GET['wpm_preview']) // phpcs:ignore WordPress.Security.NonceVerification -- read-only flag
			&& did_action('init')
			&& current_user_can('edit_theme_options');
	}

	public static function ajax_preview() {
		check_ajax_referer('wpm_theme_preview', 'nonce');
		if (!current_user_can('edit_theme_options')) {
			wp_send_json_error(null, 403);
		}
		$input = isset($_POST[self::$option]) ? wp_unslash($_POST[self::$option]) : []; // phpcs:ignore WordPress.Security.ValidatedSanitizedInput -- validated below
		set_transient(self::preview_key(), self::validate_all(is_array($input) ? $input : [], true), HOUR_IN_SECONDS);
		wp_send_json_success(['url' => add_query_arg('wpm_preview', '1', home_url('/'))]);
	}

	/* =========================================================== validation */

	private static function valid_size($value) {
		if ($value === '0' || preg_match('/^\d{1,4}(\.\d{1,4})?(px|rem|em|%|vw|vh|pt|ch)$/', $value)) {
			return true;
		}
		// Fluid values, e.g. clamp(1rem, 4vw, 2rem) or min(90vw, 1200px)
		return strlen($value) <= 80 && (bool) preg_match('/^(clamp|min|max)\([0-9a-z.%+\-*\/ ,]+\)$/', $value);
	}

	/** Return the cleaned value, or null when invalid. */
	private static function validate_field(array $def, $value) {
		$value = trim((string) $value);
		$type  = $def['type'];

		if ($value === '' && isset($def['empty']) && $def['empty'] !== '' && !in_array($type, ['nav', 'media'], true)) {
			return '';
		}

		switch ($type) {
			case 'color':
				if ($value === '' && ($def['empty'] ?? '') !== '') {
					return '';
				}
				$hex = sanitize_hex_color($value);
				return $hex ? strtolower($hex) : null;
			case 'bool':
				return $value === '1' ? '1' : '0';
			case 'select':
			case 'transform':
				$choices = $type === 'transform'
					? ['none' => 1, 'uppercase' => 1, 'lowercase' => 1, 'capitalize' => 1]
					: $def['choices'];
				return array_key_exists($value, $choices) ? $value : null;
			case 'font':
				return array_key_exists($value, self::fonts()) ? $value : null;
			case 'weight':
				return array_key_exists($value, self::weights()) ? $value : null;
			case 'size':
				return self::valid_size($value) ? $value : null;
			case 'line_height':
				return preg_match('/^\d(\.\d{1,3})?$/', $value) && (float) $value >= 0.8 && (float) $value <= 3 ? $value : null;
			case 'letter_spacing':
				return preg_match('/^-?\d{1,2}(\.\d{1,3})?(px|em|rem)?$/', $value) ? $value : null;
			case 'number':
				if (!preg_match('/^\d+$/', $value)) {
					return null;
				}
				$n = (int) $value;
				return $n >= $def['min'] && $n <= $def['max'] ? (string) $n : null;
			case 'text':
				return sanitize_text_field($value);
			case 'html':
				return wp_kses_post($value);
			case 'url':
				return $value === '' ? '' : (esc_url_raw($value, ['http', 'https', 'mailto', 'tel']) ?: null);
			case 'media':
				$id = absint($value);
				return $id === 0 || wp_attachment_is_image($id) ? (string) $id : null;
			case 'nav':
				return self::valid_menu($value);
			case 'css':
				$css = wp_strip_all_tags($value);
				return stripos($css, '</style') === false ? $css : null;
		}
		return null;
	}

	/**
	 * Validate a full [tab][section][field] array. Missing keys keep the saved value,
	 * invalid values keep the saved value and (unless $quiet) add a settings error.
	 */
	public static function validate_all(array $input, $quiet = false) {
		$current = self::saved();
		$clean   = [];
		foreach (self::schema() as $tab => $tab_def) {
			foreach ($tab_def['sections'] as $section => $section_def) {
				foreach ($section_def['fields'] as $field => $def) {
					$keep = $current[$tab][$section][$field];
					if (!isset($input[$tab][$section][$field]) || !is_scalar($input[$tab][$section][$field])) {
						$clean[$tab][$section][$field] = $keep;
						continue;
					}
					if ($def['type'] === 'css' && !current_user_can('edit_css')) {
						$clean[$tab][$section][$field] = $keep;
						continue;
					}
					$raw   = (string) $input[$tab][$section][$field];
					$value = self::validate_field($def, $raw);
					if ($value === null) {
						if (!$quiet) {
							add_settings_error(
								self::$option,
								"invalid-$tab-$section-$field",
								sprintf(
									'%s → %s → %s: “%s” is not valid, so the previous value was kept.',
									esc_html($tab_def['label']),
									esc_html($section_def['label']),
									esc_html($def['label']),
									esc_html($raw)
								)
							);
						}
						$value = $keep;
					}
					$clean[$tab][$section][$field] = $value;
				}
			}
		}
		return $clean;
	}

	public static function sanitize($input) {
		if (!is_array($input)) {
			return self::saved();
		}
		if (!empty($input['_reset'])) {
			add_settings_error(self::$option, 'reset', 'All theme options were reset to their defaults.', 'updated');
			return self::defaults();
		}
		if (isset($input['_import']) && trim((string) $input['_import']) !== '') {
			$data = json_decode((string) $input['_import'], true);
			if (!is_array($data)) {
				add_settings_error(self::$option, 'import', 'Import failed: the text is not valid JSON exported from Theme Options.');
				return self::saved();
			}
			add_settings_error(self::$option, 'imported', 'Theme options imported.', 'updated');
			return self::validate_all($data);
		}
		return self::validate_all($input);
	}

	/* ================================================================ menus */

	/** '0', 'c:<classic menu id>' or 'n:<wp_navigation id>'; null when invalid. */
	public static function valid_menu($value) {
		$value = trim((string) $value);
		if ($value === '' || $value === '0') {
			return '0';
		}
		if (ctype_digit($value)) { // saved by an earlier theme version
			$value = 'n:' . $value;
		}
		if (preg_match('/^c:(\d+)$/', $value, $m)) {
			return is_nav_menu((int) $m[1]) ? $value : null;
		}
		if (preg_match('/^n:(\d+)$/', $value, $m)) {
			$post = get_post((int) $m[1]);
			return $post && $post->post_type === 'wp_navigation' && $post->post_status === 'publish' ? $value : null;
		}
		return null;
	}

	/** Menus that can be chosen: classic (Appearance → Menus) and Site Editor navigation menus. */
	public static function menu_choices() {
		$choices = ['classic' => [], 'block' => []];
		foreach (wp_get_nav_menus() as $menu) {
			$choices['classic'][] = [
				'value' => 'c:' . $menu->term_id,
				'label' => $menu->name,
				'edit'  => admin_url('nav-menus.php?action=edit&menu=' . $menu->term_id),
			];
		}
		$posts = get_posts(['post_type' => 'wp_navigation', 'post_status' => 'publish', 'numberposts' => 100, 'orderby' => 'title', 'order' => 'ASC']);
		foreach ($posts as $post) {
			$choices['block'][] = [
				'value' => 'n:' . $post->ID,
				'label' => $post->post_title ?: '#' . $post->ID,
				'edit'  => admin_url('site-editor.php?p=' . rawurlencode('/wp_navigation/' . $post->ID)),
			];
		}
		return $choices;
	}

	/** Keep Appearance → Menus → "Manage locations" in step with the options. */
	public static function sync_menu_locations($values) {
		if (!is_array($values)) {
			return;
		}
		$locations = get_theme_mod('nav_menu_locations', []);
		$locations = is_array($locations) ? $locations : [];
		$map = [
			'header' => $values['header']['menu']['menu'] ?? '0',
			'footer' => $values['footer']['general']['menu'] ?? '0',
		];
		foreach ($map as $location => $value) {
			if (preg_match('/^c:(\d+)$/', (string) $value, $m)) {
				$locations[$location] = (int) $m[1];
			} else {
				unset($locations[$location]);
			}
		}
		set_theme_mod('nav_menu_locations', $locations);
	}

	public static function ajax_list_menus() {
		check_ajax_referer('wpm_theme_preview', 'nonce');
		if (!current_user_can('edit_theme_options')) {
			wp_send_json_error(null, 403);
		}
		wp_send_json_success(self::menu_choices());
	}

	/** Create a classic menu, pre-filled with Home + the top-level pages. */
	public static function ajax_create_menu() {
		check_ajax_referer('wpm_theme_preview', 'nonce');
		if (!current_user_can('edit_theme_options')) {
			wp_send_json_error(['message' => 'You are not allowed to manage menus.'], 403);
		}
		$name = sanitize_text_field(wp_unslash($_POST['name'] ?? '')); // phpcs:ignore WordPress.Security.NonceVerification -- checked above
		if ($name === '' || strlen($name) > 60) {
			wp_send_json_error(['message' => 'Please enter a menu name (up to 60 characters).']);
		}
		$menu_id = wp_create_nav_menu($name);
		if (is_wp_error($menu_id)) {
			wp_send_json_error(['message' => $menu_id->get_error_message()]);
		}

		wp_update_nav_menu_item($menu_id, 0, [
			'menu-item-title'  => 'Home',
			'menu-item-url'    => home_url('/'),
			'menu-item-type'   => 'custom',
			'menu-item-status' => 'publish',
		]);
		$front = (int) get_option('page_on_front');
		foreach (get_pages(['parent' => 0, 'sort_column' => 'menu_order,post_title', 'number' => 8]) as $page) {
			if ($page->ID === $front) {
				continue;
			}
			wp_update_nav_menu_item($menu_id, 0, [
				'menu-item-title'     => $page->post_title,
				'menu-item-object'    => 'page',
				'menu-item-object-id' => $page->ID,
				'menu-item-type'      => 'post_type',
				'menu-item-status'    => 'publish',
			]);
		}

		wp_send_json_success([
			'value'   => 'c:' . $menu_id,
			'label'   => $name,
			'edit'    => admin_url('nav-menus.php?action=edit&menu=' . $menu_id),
			'choices' => self::menu_choices(),
		]);
	}

