	public static function register_setting() {
		register_setting(self::GROUP, self::$option, [
			'type'              => 'array',
			'sanitize_callback' => [__CLASS__, 'sanitize'],
			'default'           => self::defaults(),
			'show_in_rest'      => false,
		]);
	}

	public static function admin_assets($hook) {
		if ($hook !== 'appearance_page_' . self::PAGE) {
			return;
		}
		wp_enqueue_media();
		wp_enqueue_style('wp-color-picker');
		wp_enqueue_style('wpm-theme-options', self::asset_url('assets/admin.css'), [], self::asset_version('assets/admin.css'));
		wp_enqueue_script('wpm-theme-options', self::asset_url('assets/admin.js'), ['jquery', 'wp-color-picker'], self::asset_version('assets/admin.js'), true);
		wp_add_inline_script('wpm-theme-options', 'window.wpmThemeOptions = ' . wp_json_encode([
			'ajaxUrl' => admin_url('admin-ajax.php'),
			'nonce'   => wp_create_nonce('wpm_theme_preview'),
			'option'  => self::$option,
		]) . ';', 'before');
	}

	private static function field_name($tab, $section, $field) {
		return self::$option . "[$tab][$section][$field]";
	}

	private static function render_field($tab, $section, $field, array $def, $value, $in_table = false) {
		$id   = "wpm-$tab-$section-$field";
		$name = self::field_name($tab, $section, $field);
		$attr = sprintf('id="%s" name="%s"', esc_attr($id), esc_attr($name));
		$type = $def['type'];
		$wide = in_array($type, ['html', 'css', 'media', 'nav'], true) ? ' wpm-field--wide' : '';

		if ($type === 'bool') {
			printf(
				'<label class="wpm-field wpm-field--bool" for="%1$s"><input type="hidden" name="%2$s" value="0"><input type="checkbox" id="%1$s" name="%2$s" value="1" %3$s><span>%4$s</span></label>',
				esc_attr($id), esc_attr($name), checked($value, '1', false), esc_html($def['label'])
			);
			return;
		}

		echo '<div class="wpm-field wpm-field--' . esc_attr($type) . $wide . '">';
		if (!$in_table) {
			echo '<label for="' . esc_attr($id) . '">' . esc_html($def['label']) . '</label>';
		}

		switch ($type) {
			case 'color':
				printf(
					'<input type="text" class="wpm-color" %s value="%s" data-default-color="%s">',
					$attr, esc_attr($value), esc_attr($def['default']) // phpcs:ignore WordPress.Security.EscapeOutput
				);
				if (!empty($def['empty'])) {
					echo '<small class="description">Empty = ' . esc_html($def['empty']) . '</small>';
				}
				break;

			case 'font':
				echo '<select ' . $attr . '>'; // phpcs:ignore WordPress.Security.EscapeOutput
				if (!empty($def['empty'])) {
					printf('<option value="" %s>%s</option>', selected($value, '', false), esc_html($def['empty']));
				}
				foreach (['System fonts' => false, 'Google Fonts' => true] as $group => $google) {
					echo '<optgroup label="' . esc_attr($group) . '">';
					foreach (self::fonts() as $slug => $font) {
						if ((bool) $font[2] === $google) {
							printf('<option value="%s" %s>%s</option>', esc_attr($slug), selected($value, $slug, false), esc_html($font[0]));
						}
					}
					echo '</optgroup>';
				}
				echo '</select>';
				break;

			case 'weight':
			case 'select':
			case 'transform':
				if ($type === 'weight') {
					$choices = self::weights();
				} elseif ($type === 'transform') {
					$choices = ['none' => 'Normal', 'uppercase' => 'UPPERCASE', 'lowercase' => 'lowercase', 'capitalize' => 'Capitalize'];
				} else {
					$choices = $def['choices'];
				}
				echo '<select ' . $attr . '>'; // phpcs:ignore WordPress.Security.EscapeOutput
				if (!empty($def['empty'])) {
					printf('<option value="" %s>%s</option>', selected($value, '', false), esc_html($def['empty']));
				}
				foreach ($choices as $key => $label) {
					printf('<option value="%s" %s>%s</option>', esc_attr($key), selected($value, (string) $key, false), esc_html($label));
				}
				echo '</select>';
				break;

			case 'nav':
				$value = self::valid_menu($value) ?? '0';
				if ($value === '0') {
					// A menu assigned in Appearance → Menus → Manage Locations counts as selected here.
					$locations = get_nav_menu_locations();
					if (!empty($locations[$def['location']]) && is_nav_menu($locations[$def['location']])) {
						$value = 'c:' . (int) $locations[$def['location']];
					}
				}
				$choices = self::menu_choices();
				printf('<select class="wpm-nav-select" data-empty="%s" %s>', esc_attr($def['empty']), $attr); // phpcs:ignore WordPress.Security.EscapeOutput
				printf('<option value="0" %s>%s</option>', selected($value, '0', false), esc_html($def['empty']));
				foreach (['classic' => 'Menus', 'block' => 'Site Editor menus'] as $group => $label) {
					if ($choices[$group]) {
						echo '<optgroup label="' . esc_attr($label) . '" data-group="' . esc_attr($group) . '">';
						foreach ($choices[$group] as $menu) {
							printf(
								'<option value="%s" data-edit="%s" %s>%s</option>',
								esc_attr($menu['value']), esc_url($menu['edit']), selected($value, $menu['value'], false), esc_html($menu['label'])
							);
						}
						echo '</optgroup>';
					}
				}
				echo '</select>';
				printf(
					'<span class="wpm-menu-actions"><button type="button" class="button wpm-menu-create" data-name="%s">＋ Create new menu</button> '
					. '<a class="button wpm-menu-edit" href="#" target="_blank" rel="noopener" hidden>Edit menu items ↗</a> '
					. '<a class="button-link" href="%s" target="_blank" rel="noopener">All menus ↗</a></span>',
					esc_attr(ucfirst($def['location']) . ' menu'),
					esc_url(admin_url('nav-menus.php'))
				);
				echo '<small class="description">Add pages, links and submenus in the menu editor (opens in a new tab). The list and preview refresh when you come back.</small>';
				break;

			case 'media':
				$src = $value !== '0' ? wp_get_attachment_image_url((int) $value, 'medium') : '';
				printf('<input type="hidden" class="wpm-media-id" %s value="%s">', $attr, esc_attr($value)); // phpcs:ignore WordPress.Security.EscapeOutput
				echo '<div class="wpm-media">';
				printf('<img class="wpm-media-preview" src="%s" alt="" %s>', esc_url($src), $src ? '' : 'hidden');
				echo '<button type="button" class="button wpm-media-select">' . ($src ? 'Replace logo' : 'Choose logo') . '</button> ';
				printf('<button type="button" class="button-link wpm-media-remove" %s>Remove</button>', $src ? '' : 'hidden');
				echo '</div>';
				break;

			case 'html':
				printf('<textarea rows="3" class="large-text" %s>%s</textarea>', $attr, esc_textarea($value)); // phpcs:ignore WordPress.Security.EscapeOutput
				break;

			case 'css':
				$disabled = current_user_can('edit_css') ? '' : ' disabled';
				printf('<textarea rows="12" class="large-text code" spellcheck="false" %s%s>%s</textarea>', $attr, $disabled, esc_textarea($value)); // phpcs:ignore WordPress.Security.EscapeOutput
				break;

			case 'number':
				printf('<input type="number" min="%d" max="%d" value="%s" %s>', (int) $def['min'], (int) $def['max'], esc_attr($value), $attr); // phpcs:ignore WordPress.Security.EscapeOutput
				break;

			case 'line_height':
				printf('<input type="number" step="0.05" min="0.8" max="3" value="%s" %s>', esc_attr($value), $attr); // phpcs:ignore WordPress.Security.EscapeOutput
				break;

			case 'url':
				printf('<input type="url" class="regular-text" placeholder="https://" value="%s" %s>', esc_attr($value), $attr); // phpcs:ignore WordPress.Security.EscapeOutput
				break;

			default: // text, size, letter_spacing
				$placeholders = ['size' => 'e.g. 1rem, 18px, clamp(…)', 'letter_spacing' => 'e.g. 0, 0.02em'];
				printf(
					'<input type="text" class="%s" value="%s" placeholder="%s" %s>',
					$type === 'text' ? 'regular-text' : 'code',
					esc_attr($value),
					esc_attr($placeholders[$type] ?? ''),
					$attr // phpcs:ignore WordPress.Security.EscapeOutput
				);
		}

		if (!empty($def['help'])) {
			echo '<small class="description">' . esc_html($def['help']) . '</small>';
		}
		echo '</div>';
	}

	private static function render_section($tab, $section, array $section_def, array $values) {
		echo '<fieldset class="wpm-section">';
		echo '<legend>' . esc_html($section_def['label']) . '</legend>';
		if (!empty($section_def['description'])) {
			echo '<p class="description">' . esc_html($section_def['description']) . '</p>';
		}
		if (!empty($section_def['action'])) {
			printf(
				'<p><a class="button" href="%s" target="_blank" rel="noopener">%s</a></p>',
				esc_url(admin_url($section_def['action']['url'])),
				esc_html($section_def['action']['label'])
			);
		}
		echo '<div class="wpm-grid">';
		foreach ($section_def['fields'] as $field => $def) {
			self::render_field($tab, $section, $field, $def, $values[$tab][$section][$field]);
		}
		echo '</div>';

		// Typography: one table for the six heading levels.
		if ($tab === 'typography' && $section === 'headings') {
			$sections = self::schema()['typography']['sections'];
			echo '<table class="wpm-levels"><thead><tr><th>Level</th><th>Size</th><th>Weight</th></tr></thead><tbody>';
			foreach (self::HEADING_LEVELS as $level) {
				echo '<tr><th scope="row">' . esc_html(strtoupper($level)) . '</th><td>';
				self::render_field('typography', $level, 'size', $sections[$level]['fields']['size'], $values['typography'][$level]['size'], true);
				echo '</td><td>';
				self::render_field('typography', $level, 'weight', $sections[$level]['fields']['weight'], $values['typography'][$level]['weight'], true);
				echo '</td></tr>';
			}
			echo '</tbody></table>';
		}
		echo '</fieldset>';
	}

	public static function render_page() {
		if (!current_user_can('edit_theme_options')) {
			return;
		}
		delete_transient(self::preview_key()); // the preview starts from the saved values
		$values = self::saved();
		$schema = self::schema();
		$tabs   = array_map(function ($t) {
			return $t['label'];
		}, $schema) + ['tools' => 'Import / Export'];
		?>
		<div class="wrap wpm-options">
			<h1>Theme Options</h1>
			<?php settings_errors(); ?>

			<nav class="nav-tab-wrapper wpm-tabs">
				<?php foreach ($tabs as $key => $label) : ?>
					<a href="#<?php echo esc_attr($key); ?>" class="nav-tab" data-tab="<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></a>
				<?php endforeach; ?>
			</nav>

			<div class="wpm-layout">
				<form method="post" action="options.php" id="wpm-options-form" class="wpm-form">
					<?php settings_fields(self::GROUP); ?>

					<?php foreach ($schema as $tab => $tab_def) : ?>
						<div class="wpm-panel" data-panel="<?php echo esc_attr($tab); ?>">
							<?php
							foreach ($tab_def['sections'] as $section => $section_def) {
								if ($tab === 'typography' && in_array($section, self::HEADING_LEVELS, true)) {
									continue;
								}
								self::render_section($tab, $section, $section_def, $values);
							}
							?>
						</div>
					<?php endforeach; ?>

					<div class="wpm-panel" data-panel="tools">
						<fieldset class="wpm-section">
							<legend>Export</legend>
							<p class="description">Copy these settings to use them on another site with this theme.</p>
							<textarea class="large-text code" rows="8" readonly onclick="this.select()"><?php echo esc_textarea(wp_json_encode($values, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)); ?></textarea>
						</fieldset>
						<fieldset class="wpm-section">
							<legend>Import</legend>
							<p class="description">Paste exported settings and click “Import”. Invalid values are skipped.</p>
							<textarea class="large-text code" rows="6" name="<?php echo esc_attr(self::$option); ?>[_import]" spellcheck="false"></textarea>
							<p><button type="submit" class="button">Import</button></p>
						</fieldset>
						<fieldset class="wpm-section">
							<legend>Reset</legend>
							<p class="description">Restore every option on every tab to the theme defaults.</p>
							<button type="submit" class="button button-link-delete" name="<?php echo esc_attr(self::$option); ?>[_reset]" value="1"
								onclick="return confirm('Reset ALL theme options to their defaults?');">Reset all options</button>
						</fieldset>
					</div>

					<div class="wpm-savebar">
						<?php submit_button('Save changes', 'primary', 'submit', false); ?>
						<span class="wpm-status" aria-live="polite"></span>
					</div>
				</form>

				<aside class="wpm-preview">
					<div class="wpm-preview__bar">
						<strong>Live preview</strong>
						<span class="wpm-devices">
							<button type="button" class="button is-active" data-device="desktop" title="Desktop">Desktop</button>
							<button type="button" class="button" data-device="tablet" title="Tablet">Tablet</button>
							<button type="button" class="button" data-device="mobile" title="Mobile">Mobile</button>
						</span>
					</div>
